import * as T from "three";

export const ENVIRONMENT_MAP_URL = "/models/silo-engolfamento/environment-pmrem-256.png";
export const ENVIRONMENT_MAP_SIZE = { width: 768, height: 1024 } as const;

export interface EnvironmentMapResource {
  texture: T.Texture;
  /** Final owner only. A context GPU release may dispose the texture without
   * closing its CPU bitmap; mark needsUpdate to upload it to a restored context. */
  dispose(): void;
}

function abortError() {
  return new DOMException("Carga dos reflexos cancelada", "AbortError");
}

/** Pre-filtered local CubeUV pixels, generated by bake-environment-map.mjs.
 * PNG stores linear values rather than a display image; never apply sRGB
 * decoding, Y flipping, mip generation, or runtime PMREM filtering to it. */
export async function loadEnvironmentMap(signal?: AbortSignal): Promise<EnvironmentMapResource> {
  if (signal?.aborted) throw abortError();
  const response = await fetch(ENVIRONMENT_MAP_URL, signal ? { signal } : {});
  if (!response.ok) throw new Error(`Reflexos locais: recurso HTTP ${response.status}`);
  const blob = await response.blob();
  if (signal?.aborted) throw abortError();
  let image: ImageBitmap;
  try {
    image = await createImageBitmap(blob, {
      colorSpaceConversion: "none",
      premultiplyAlpha: "none",
      imageOrientation: "none",
    });
  } catch (error) {
    if (signal?.aborted) throw abortError();
    throw new Error("Reflexos locais: não foi possível decodificar a imagem", { cause: error });
  }
  if (signal?.aborted) {
    image.close();
    throw abortError();
  }
  if (image.width !== ENVIRONMENT_MAP_SIZE.width || image.height !== ENVIRONMENT_MAP_SIZE.height) {
    image.close();
    throw new Error("Reflexos locais: dimensões do recurso inválidas");
  }
  const texture = new T.Texture(image);
  texture.name = "Nexus_local_linear_PMREM_256";
  texture.mapping = T.CubeUVReflectionMapping;
  texture.colorSpace = T.LinearSRGBColorSpace;
  texture.flipY = false;
  texture.generateMipmaps = false;
  texture.minFilter = texture.magFilter = T.LinearFilter;
  texture.needsUpdate = true;
  let disposed = false;
  return {
    texture,
    dispose() {
      if (disposed) return;
      disposed = true;
      texture.dispose();
      image.close();
    },
  };
}
